package io.github.jesterportfolio.hearth.travel;

import io.github.jesterportfolio.hearth.exploration.*;
import io.github.jesterportfolio.hearth.persistence.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;

class FastTravelTest {
    private final TravelContent.Station a=new TravelContent.Station("a","village",new TravelContent.Point(2,64,2),"STONE",new TravelContent.Point(2.5,64,1.5),0,0),b=new TravelContent.Station("b","outpost",new TravelContent.Point(11,64,11),"STONE",new TravelContent.Point(11.5,64,10.5),0,0);
    private final TravelContent content=new TravelContent(Map.of("a",a,"b",b));
    private static ExplorationView data(boolean target){var x=ExplorationView.empty();var places=new ArrayList<ExplorationView.Place>();places.add(new ExplorationView.Place("village","마을","평원","거점","공개 위치","발견",true,true,true));if(target)places.add(new ExplorationView.Place("outpost","초소","평원","거점","공개 위치","발견",true,true,true));return new ExplorationView(true,List.of(),places,List.of(),List.of(),List.of(),x.story(),x.conditions(),null,Set.of(),List.of());}
    private class Port implements FastTravel.Port {
        ServerProgressAccess.Context ctx=new ServerProgressAccess().forVerifiedServerLink(UUID.randomUUID(),UUID.randomUUID());Object token=new Object();UUID world=UUID.randomUUID();long gen=1;boolean valid=true,eligible=true,access=true,facility=true,frozen,dirty=true,moveOk=true;int reads,saves,moves,releases;TravelContent.Point point=a.arrival();ExplorationView view=data(true);CompletableFuture<Void> save=CompletableFuture.completedFuture(null),preparing=CompletableFuture.completedFuture(null);CompletableFuture<ExplorationView> reading;
        public ServerProgressAccess.Context context(){return ctx;}public Object session(){return token;}public UUID world(){return world;}public long generation(){return gen;}public TravelContent.Point position(){return point;}public boolean current(){return valid;}public boolean eligible(){return eligible;}public boolean access(TravelContent.Station s){return access;}public boolean facility(TravelContent.Station s){return facility;}public void freeze(boolean value){frozen=value;}public CompletionStage<ExplorationView> read(){reads++;return reading==null?CompletableFuture.completedFuture(view):reading;}public CompletionStage<Void> save(){saves++;return save.thenRun(()->dirty=false);}public CompletionStage<Void> prepare(TravelContent.Station s,java.util.function.BooleanSupplier valid){return preparing;}public CompletionStage<Boolean> move(TravelContent.Station s,java.util.function.BooleanSupplier valid){moves++;if(moveOk&&valid.getAsBoolean())point=s.arrival();return CompletableFuture.completedFuture(moveOk);}public void release(){releases++;}
    }
    private FastTravel travel(){return new FastTravel(content,Runnable::run,()->{});}
    private void failure(CompletionStage<?> work,String code){var e=assertThrows(CompletionException.class,()->work.toCompletableFuture().join());Throwable t=e;while(t.getCause()!=null)t=t.getCause();assertEquals(code,t.getMessage());}
    @Test void requiresBothVisitedPersonalHubs(){var p=new Port();p.view=data(false);var t=travel();assertTrue(t.destinations(p.view,p,"a").isEmpty());failure(t.start(p,"a","b",UUID.randomUUID()),"TRAVEL_LOCKED");assertEquals(0,p.saves);assertEquals(0,p.moves);assertFalse(p.frozen);}
    @Test void sourceMustBeFacilityInRangeAndAccessAllowed(){for(int i=0;i<4;i++){var p=new Port();if(i==0)p.facility=false;if(i==1)p.point=new TravelContent.Point(99,64,99);if(i==2)p.access=false;if(i==3)p.eligible=false;failure(travel().start(p,"a","b",UUID.randomUUID()),"TRAVEL_FACILITY_REQUIRED");assertEquals(0,p.saves);}}
    @Test void saveMustFinishBeforeMoveAndDuplicateDoesNotMoveTwice(){var p=new Port();p.save=new CompletableFuture<>();var t=travel();var id=UUID.randomUUID();var result=t.start(p,"a","b",id);assertSame(result,t.start(p,"a","b",id));assertTrue(p.frozen);assertEquals(0,p.moves);assertFalse(t.barrier(p.ctx.storyRunId()).toCompletableFuture().isDone());p.save.complete(null);result.toCompletableFuture().join();assertEquals(1,p.moves);assertEquals(2,p.reads);assertFalse(p.dirty);assertFalse(p.frozen);assertEquals(FastTravel.Phase.DONE,t.phase(p));}
    @Test void databaseFailureKeepsDirtyAndHoldWithoutMoving(){var p=new Port();p.save=CompletableFuture.failedFuture(new IllegalStateException("DB_FAILURE"));var t=travel();failure(t.start(p,"a","b",UUID.randomUUID()),"DB_FAILURE");assertTrue(p.dirty);assertEquals(0,p.moves);assertEquals(FastTravel.Phase.HOLD,t.phase(p));failure(t.start(p,"a","b",UUID.randomUUID()),"TRAVEL_BUSY_OR_HOLD");}
    @Test void targetIsCheckedAgainAfterSave(){var p=new Port();p.save=new CompletableFuture<>();var t=travel();var result=t.start(p,"a","b",UUID.randomUUID());p.view=data(false);p.save.complete(null);failure(result,"TRAVEL_LOCKED");assertEquals(0,p.moves);}
    @Test void generationWorldSessionAndAccessChangesRejectStaleResults(){for(int i=0;i<4;i++){var p=new Port();p.save=new CompletableFuture<>();var t=travel();var result=t.start(p,"a","b",UUID.randomUUID());if(i==0)p.gen++;if(i==1)p.world=UUID.randomUUID();if(i==2)p.token=new Object();if(i==3)p.access=false;p.save.complete(null);failure(result,"TRAVEL_STALE");assertEquals(0,p.moves);}}
    @Test void quitCancelRejectsLatePrepareAndPreservesDrainBarrier(){var p=new Port();p.preparing=new CompletableFuture<>();var t=travel();var result=t.start(p,"a","b",UUID.randomUUID());t.cancel(p);failure(result,"TRAVEL_CANCELLED");assertFalse(p.frozen);assertFalse(t.settled(p.ctx.storyRunId()));p.preparing.complete(null);assertTrue(t.settled(p.ctx.storyRunId()));assertEquals(0,p.moves);assertEquals(1,p.releases);t.cancel(p);assertEquals(1,p.releases);}
    @Test void failedTeleportNeverReportsSuccess(){var p=new Port();p.moveOk=false;var t=travel();failure(t.start(p,"a","b",UUID.randomUUID()),"TRAVEL_MOVE_FAILED");assertEquals(FastTravel.Phase.HOLD,t.phase(p));assertEquals(a.arrival(),p.point);}
    @Test void differentPlayersAndRunsRemainIndependent(){var p=new Port();var q=new Port();p.save=new CompletableFuture<>();var t=travel();var result=t.start(p,"a","b",UUID.randomUUID());t.start(q,"a","b",UUID.randomUUID()).toCompletableFuture().join();assertEquals(0,p.moves);assertEquals(1,q.moves);p.save.complete(null);result.toCompletableFuture().join();assertEquals(1,p.moves);}
    @Test void rejectedAndMissingReadIsNotEmptySuccess(){var p=new Port();p.reading=CompletableFuture.failedFuture(new IllegalStateException("READ_FAILURE"));var t=travel();failure(t.start(p,"a","b",UUID.randomUUID()),"READ_FAILURE");assertEquals(FastTravel.Phase.REJECTED,t.phase(p));assertEquals(0,p.saves);}
    @Test void closeAndNewSessionCannotApplyPreviousCallback(){var p=new Port();p.reading=new CompletableFuture<>();var t=travel();var result=t.start(p,"a","b",UUID.randomUUID());t.close();failure(result,"TRAVEL_CLOSED");p.token=new Object();p.reading.complete(data(true));assertEquals(0,p.moves);assertTrue(t.settled(p.ctx.storyRunId()));}
    @Test void oldQuitCannotForgetNewSessionAndCompletedQuitReleasesEntry(){var p=new Port();var t=travel();t.start(p,"a","b",UUID.randomUUID()).toCompletableFuture().join();var q=new Port();q.ctx=p.ctx;t.start(q,"a","b",UUID.randomUUID()).toCompletableFuture().join();t.forget(p);assertEquals(FastTravel.Phase.DONE,t.phase(q));t.forget(q);assertNull(t.phase(q));}
    @Test void emptyArrowSlotsCannotOpenUnregisteredPages(){assertFalse(FastTravel.pageAvailable(1,-1));assertFalse(FastTravel.pageAvailable(1,1));assertFalse(FastTravel.pageAvailable(0,1));assertTrue(FastTravel.pageAvailable(46,1));assertFalse(FastTravel.pageAvailable(46,2));}
    @Test void runBarrierWaitsForAllPlayers(){var p=new Port();var q=new Port();q.ctx=new ServerProgressAccess().forVerifiedServerLink(p.ctx.storyRunId(),UUID.randomUUID());p.save=new CompletableFuture<>();q.save=new CompletableFuture<>();var t=travel();t.start(p,"a","b",UUID.randomUUID());t.start(q,"a","b",UUID.randomUUID());var barrier=t.barrier(p.ctx.storyRunId());assertFalse(barrier.toCompletableFuture().isDone());p.save.complete(null);assertFalse(barrier.toCompletableFuture().isDone());q.save.complete(null);barrier.toCompletableFuture().join();assertEquals(1,p.moves);assertEquals(1,q.moves);}
    @Test void pagesAreBoundedAndDoNotMutate(){var list=new ArrayList<Integer>();for(int i=0;i<91;i++)list.add(i);assertEquals(45,FastTravel.page(list,0).size());assertEquals(1,FastTravel.page(list,2).size());assertThrows(IllegalArgumentException.class,()->FastTravel.page(list,3));assertThrows(UnsupportedOperationException.class,()->FastTravel.page(list,0).clear());}
}
